const CHART_THEMES={dark:{grid:'#233041',axis:'#8fa1b5',thr:'#30d158',str:'#0a84ff',gz:'#ff453a',saver:'#0a84ff',toastOk:'#30d158',toastErr:'#ff453a'},light:{grid:'#dbe2ea',axis:'#5b6b7d',thr:'#34c759',str:'#0071e3',gz:'#ff3b30',saver:'#0071e3',toastOk:'#34c759',toastErr:'#ff3b30'}};
function systemTheme(){try{return window.matchMedia&&window.matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'}catch(e){return 'dark'}}
function resolvedTheme(){return uiTheme==='auto'?systemTheme():(uiTheme==='light'?'light':'dark')}
