function freeTermNumber(){let n=1;const used=new Set();termList.forEach(x=>{if(x.num)used.add(x.num)});while(used.has(n))n++;return n;}
function addTerminalTab(){termInited=true;const id=++termSeq,f=document.createElement('iframe');f.className='termFrame';f.title='host terminal';f.setAttribute('scrolling','no');terminalWrap.insertBefore(f,terminalHint);const b=document.createElement('button');b.className='termTab';const c=document.createElement('button');c.type='button';c.className='termTabClose';c.textContent='×';c.title=t('terminal.closeTab');c.onclick=e=>{e.stopPropagation();killTerminalTab(id)};b.appendChild(c);const num=freeTermNumber();const l=document.createElement('span');l.className='termTabLabel';l.textContent=t('terminal.tab')+' '+num;b.appendChild(l);b.onclick=()=>selectTerminalTab(id);termTabs.appendChild(b);const term={id:id,f:f,b:b,l:l,c:c,name:null,num:num,state:'loading'};termList.push(term);selectTerminalTab(id);fitTermTabLabels();updateTermTabClose();_fetchLauncherIp().then(()=>probeTerminal(term));}
function selectTerminalTab(id){termActive=id;termList.forEach(x=>{x.f.style.display=x.id===id?'':'none';x.b.classList.toggle('active',x.id===id)});const cur=termList.find(x=>x.id===id);terminalHint.textContent=!cur?t('terminal.empty'):cur.state==='loading'?t('terminal.loading'):cur.state==='fail'?termFailHint():'';}
function updateTermTabClose(){const hide=termList.length<=1;termList.forEach(x=>{x.c.style.display=hide?'none':''});}
